    @Test void writeReviewExamplesFromActualCalculations()throws Exception{
        ObjectNode examples=json.object().put("evidenceKind","SYNTHETIC_IN_MEMORY_NOT_BUSINESS_ACCEPTANCE");ObjectNode requests=json.object(),responses=json.object();ObjectNode request=input(),evaluation=eval();requests.set("recommend",demand(json));requests.set("evaluate",request);requests.set("replace",input().put("category","WHEEL").put("page",1).put("size",20));ObjectNode compare=json.object();compare.set("plans",json.array().add(input()));requests.set("compare",compare);requests.set("save",input().put("name","合成测试方案").put("note","Synthetic only").put("expectedCalculationVersion",evaluation.path("calculationVersion").asText()));responses.set("evaluate",calc.publicView(evaluation));responses.set("recommend",calc.publicView(calc.recommend(demand(json))));responses.set("compare",calc.publicView(calc.compare(compare)));ObjectNode stale=input().put("expectedCalculationVersion",evaluation.path("calculationVersion").asText());BoardTestData.find(data,"quotes","SYN-Q-DECK").put("version",2).put("amountCents",201);responses.set("priceChanged",calc.publicView(calc.evaluate(stale)));
        ((ObjectNode)rule("WHEEL_TRUCK_RISER").path("conditions")).put("riserMode","REQUIRED").put("riserMinMm",3);responses.set("linkedReplacement",calc.publicView(calc.replacements(requests.path("replace"))));data=(ObjectNode)BoardTestData.real(json);data.put("catalogVersion","0".repeat(64));responses.set("recordedDraftRecommend",calc.publicView(calc.recommend(demand(json))));examples.set("requests",requests);examples.set("responses",responses);java.nio.file.Path path=java.nio.file.Path.of("target/test-evidence/board/B01-api-examples.json");java.nio.file.Files.createDirectories(path.getParent());java.nio.file.Files.writeString(path,examples.toPrettyString(),java.nio.charset.StandardCharsets.UTF_8);
    }
